function applyCollisionPatches(finder) {
  const x3 = 2597;
  const z = 3608;
  const level = 0;
  finder.setWalkable(x3, z, level, true);
  finder.clearWallBits(x3, z, level, WALL_E | WALL_W);
  finder.clearWallBits(x3 - 1, z, level, WALL_E);
  finder.clearWallBits(x3 + 1, z, level, WALL_W);
  finder.orExitMask(x3, z, level, EXIT_E | EXIT_W);
  finder.orExitMask(x3 - 1, z, level, EXIT_E);
  finder.orExitMask(x3 + 1, z, level, EXIT_W);
}
