var earlyQueue = [];
var midifade = 0;
var midivol = DEFAULT_MIDIVOL;
var midiCmd = "none";
var pendingMidi = null;
var midiFadingIn = false;
var midiFadingOut = false;
var midiFadeVol = 0;
var loopHandle = null;
async function loadFlorestan(b) {
  for (const url of FLORESTAN_URLS) {
    try {
      const res = await fetch(url);
      if (!res.ok) {
        continue;
      }
      const buf = await res.arrayBuffer();
      if (buf.byteLength < 1000) {
        continue;
      }
      await b.setSoundfont(buf);
      console.info(`[midi] setSoundfont Florestan from ${url} (${buf.byteLength} bytes)`);
      return true;
    } catch {}
  }
  console.warn("[midi] SCC1_Florestan.sf2 missing — MIDI disabled until bank available");
  return false;
}
function applyMidivol(midivolJava) {
  if (!backend) {
    return;
  }
  backend.setMidivol(midivolJava);
}
function signlinkPlayMidi() {
  if (!backend) {
    return;
  }
  if (midiFadingOut) {
    return;
  }
  if (!midiFadingIn && midifade !== 0 && backend.isPlaying()) {
    midiFadingOut = true;
    midiFadeVol = midivol;
    return;
  }
  if (!pendingMidi) {
    return;
  }
  try {
    const loop = midifade !== 0;
    const mid = pendingMidi;
    const onErr = (e) => console.warn("[midi] play failed", e);
    if (midifade !== 0 && midiFadingIn) {
      midiFadingOut = false;
      midiFadeVol = 0;
      applyMidivol(0);
      backend.play(mid, loop).catch(onErr);
    } else {
      applyMidivol(midivol);
      backend.play(mid, loop).then(() => applyMidivol(midivol)).catch(onErr);
    }
  } catch (e) {
    console.warn("[midi] play failed", e);
  }
}
function audioLoop() {
  if (!backend) {
    return;
  }
  if (midiFadingIn) {
    midiFadeVol += 8;
    if (midiFadeVol > midivol) {
      midiFadeVol = midivol;
    }
    applyMidivol(midiFadeVol);
    if (midiFadeVol === midivol) {
      midiFadingIn = false;
    }
  } else if (midiFadingOut) {
    midiFadeVol -= 8;
    if (midiFadeVol < 0) {
      midiFadeVol = 0;
    }
    applyMidivol(midiFadeVol);
    if (midiFadeVol === 0) {
      midiFadingOut = false;
      midiFadingIn = true;
    }
  }
  if (midiCmd !== "none") {
    if (midiCmd === "stop") {
      backend.stop();
    } else if (midiCmd === "voladjust") {
      applyMidivol(midivol);
    } else if (midiCmd === "play") {
      signlinkPlayMidi();
    }
    if (!midiFadingOut) {
      midiCmd = "none";
    }
  }
}
async function init() {
  backend = new SpessaBackend;
  const ok = await loadFlorestan(backend);
  if (!ok) {
    console.warn("[midi] continuing without soundfont — plays will fail until bank loads");
  }
  applyMidivol(DEFAULT_MIDIVOL);
  if (!loopHandle) {
    loopHandle = setInterval(audioLoop, AUDIO_LOOP_MS);
  }
  ready = true;
  console.info("[midi] Jagex 377 control plane ready (Spessa + Florestan, master midivol)");
  while (earlyQueue.length) {
    const item = earlyQueue.shift();
    try {
      if (item.op === "play") {
        playMidiStock(item.data, item.fade);
      } else if (item.op === "stop") {
        stopMidiStock();
      } else if (item.op === "vol") {
        setMidiVolumeStock(item.midivol, item.applyNow);
      }
    } catch (e) {
      console.warn("[midi] early queue item failed", e);
    }
  }
}
function ensureInit() {
  if (initPromise) {
    return;
  }
  initPromise = init().catch((err) => {
    console.error("[midi] init failed", err);
  });
}
function playMidiStock(data, fade) {
  if (!data || data.length === 0) {
    return;
  }
  midifade = fade ? 1 : 0;
  pendingMidi = data instanceof Uint8Array ? data.slice() : new Uint8Array(data);
  midiCmd = "play";
  audioLoop();
}
function stopMidiStock() {
  midifade = 0;
  midiFadingIn = false;
  midiFadingOut = false;
  midiCmd = "stop";
  audioLoop();
}
function setMidiVolumeStock(midivolJava, applyNow) {
  midivol = midivolJava | 0;
  if (midivol < 0) {
    midivol = 0;
  }
  if (midivol > 128) {
    midivol = 128;
  }
  if (applyNow !== false) {
    midiCmd = "voladjust";
    audioLoop();
  }
}
function playMidi(data, _volumeIgnored, fade) {
  ensureInit();
  if (!data || data.length === 0) {
    return;
  }
  const fading = !!fade;
  if (!ready || !backend) {
    earlyQueue.push({
      op: "play",
      data: data instanceof Uint8Array ? data.slice() : new Uint8Array(data),
      fade: fading
    });
    return;
  }
  playMidiStock(data, fading);
}
function setMidiVolume(midivolJava, applyNow) {
  ensureInit();
  if (!ready || !backend) {
    earlyQueue.push({ op: "vol", midivol: midivolJava, applyNow });
    return;
  }
  setMidiVolumeStock(midivolJava, applyNow);
}
function stopMidi(_fade) {
  ensureInit();
  if (!ready || !backend) {
    earlyQueue.push({ op: "stop" });
    return;
  }
  stopMidiStock();
}
ensureInit();

// vendor/client-ts/src/config/FloType.ts
init_Packet();

class FloType {
  static numDefinitions = 0;
  static list = [];
  colour = 0;
  texture = -1;
  overlay = false;
  occlude = true;
  debugname = "";
  hue = 0;
  saturation = 0;
  lightness = 0;
  chroma = 0;
  underlayHue = 0;
  overlayHsl = 0;
  static init(config) {
    const dat = new Packet(config.read("flo.dat"));
    this.numDefinitions = dat.g2();
    this.list = new Array(this.numDefinitions);
    for (let id = 0;id < this.numDefinitions; id++) {
      if (!this.list[id]) {
        this.list[id] = new FloType;
      }
      this.list[id].decode(dat);
    }
  }
  decode(dat) {
    while (true) {
      const code = dat.g1();
      if (code === 0) {
        return;
      }
      if (code === 1) {
        this.colour = dat.g3();
        this.getHsl(this.colour);
      } else if (code === 2) {
        this.texture = dat.g1();
      } else if (code === 3) {
        this.overlay = true;
      } else if (code === 5) {
        this.occlude = false;
      } else if (code === 6) {
        this.debugname = dat.gjstr();
      } else if (code === 7) {
        const hue = this.hue;
        const saturation = this.saturation;
        const lightness = this.lightness;
        const underlayHue = this.underlayHue;
        const secondary = dat.g3();
        this.getHsl(secondary);
        this.hue = hue;
        this.saturation = saturation;
        this.lightness = lightness;
        this.underlayHue = underlayHue;
        this.chroma = underlayHue;
      } else {
        console.log("Error unrecognised config code: ", code);
      }
    }
  }
  getHsl(rgb) {
    if (rgb === 16711935) {
      rgb = 0;
    }
    const red = (rgb >> 16 & 255) / 256;
    const green = (rgb >> 8 & 255) / 256;
    const blue = (rgb & 255) / 256;
    let min = red;
    if (green < red) {
      min = green;
    }
    if (blue < min) {
      min = blue;
    }
    let max = red;
    if (green > red) {
      max = green;
    }
    if (blue > max) {
      max = blue;
    }
    let h2 = 0;
    let s = 0;
    const l = (min + max) / 2;
    if (min !== max) {
      if (l < 0.5) {
        s = (max - min) / (max + min);
      }
      if (l >= 0.5) {
        s = (max - min) / (2 - max - min);
      }
      if (red === max) {
        h2 = (green - blue) / (max - min);
      } else if (green === max) {
        h2 = (blue - red) / (max - min) + 2;
      } else if (blue === max) {
        h2 = (red - green) / (max - min) + 4;
      }
    }
    h2 /= 6;
    this.hue = h2 * 256 | 0;
    this.saturation = s * 256 | 0;
    this.lightness = l * 256 | 0;
    if (this.saturation < 0) {
      this.saturation = 0;
    } else if (this.saturation > 255) {
      this.saturation = 255;
    }
    if (this.lightness < 0) {
      this.lightness = 0;
    } else if (this.lightness > 255) {
      this.lightness = 255;
    }
    if (l > 0.5) {
      this.chroma = (1 - l) * s * 512 | 0;
    } else {
      this.chroma = l * s * 512 | 0;
    }
    if (this.chroma < 1) {
      this.chroma = 1;
    }
    this.underlayHue = h2 * this.chroma | 0;
    let hue = this.hue + (Math.random() * 16 | 0) - 8;
    if (hue < 0) {
      hue = 0;
    } else if (hue > 255) {
      hue = 255;
    }
    let saturation = this.saturation + (Math.random() * 48 | 0) - 24;
    if (saturation < 0) {
      saturation = 0;
    } else if (saturation > 255) {
      saturation = 255;
    }
    let lightness = this.lightness + (Math.random() * 48 | 0) - 24;
    if (lightness < 0) {
      lightness = 0;
    } else if (lightness > 255) {
      lightness = 255;
    }
    this.overlayHsl = FloType.getTable(hue, saturation, lightness);
  }
  static getTable(hue, saturation, lightness) {
    if (lightness > 179) {
      saturation = saturation / 2 | 0;
    }
    if (lightness > 192) {
      saturation = saturation / 2 | 0;
    }
    if (lightness > 217) {
      saturation = saturation / 2 | 0;
    }
    if (lightness > 243) {
      saturation = saturation / 2 | 0;
    }
    return ((hue / 4 | 0) << 10) + ((saturation / 32 | 0) << 7) + (lightness / 2 | 0);
  }
}

// vendor/client-ts/src/datastruct/HashTable.ts
class HashTable {
  bucketCount;
  buckets;
  constructor(size) {
    this.buckets = new Array(size);
    this.bucketCount = size;
    for (let i2 = 0;i2 < size; i2++) {
      const sentinel = this.buckets[i2] = new Linkable;
      sentinel.next = sentinel;
      sentinel.prev = sentinel;
    }
  }
  find(key) {
    const start = this.buckets[Number(key & BigInt(this.bucketCount - 1))];
    for (let node = start.next;node !== start; node = node?.next ?? null) {
      if (node && node.key === key) {
        return node;
      }
    }
    return null;
  }
  put(node, key) {
    if (node.prev) {
      node.unlink();
    }
    const sentinel = this.buckets[Number(key & BigInt(this.bucketCount - 1))];
    node.prev = sentinel.prev;
    node.next = sentinel;
    if (node.prev) {
      node.prev.next = node;
    }
    node.next.prev = node;
    node.key = key;
  }
}

// vendor/client-ts/src/datastruct/LinkList2.ts
init_Linkable2();

class LinkList2 {
  sentinel = new Linkable2;
  cursor = null;
  constructor() {
    this.sentinel.next2 = this.sentinel;
    this.sentinel.prev2 = this.sentinel;
  }
  push(node) {
    if (node.prev2) {
      node.unlink2();
    }
    node.prev2 = this.sentinel.prev2;
    node.next2 = this.sentinel;
    if (node.prev2) {
      node.prev2.next2 = node;
    }
    node.next2.prev2 = node;
  }
  popFront() {
    const node = this.sentinel.next2;
    if (node === this.sentinel) {
      return null;
    } else {
      node?.unlink2();
      return node;
    }
  }
  head() {
    const node = this.sentinel.next2;
    if (node === this.sentinel) {
      this.cursor = null;
      return null;
    }
    this.cursor = node?.next2 ?? null;
    return node;
  }
  next() {
    const node = this.cursor;
    if (node === this.sentinel) {
      this.cursor = null;
      return null;
    }
    this.cursor = node?.next2 ?? null;
    return node;
  }
  size() {
    let count = 0;
    for (let node = this.sentinel.next2;node !== this.sentinel && node; node = node.next2) {
      count++;
    }
    return count;
  }
}

// vendor/client-ts/src/datastruct/LruCache.ts
class LruCache {
  capacity;
  table = new HashTable(1024);
  history = new LinkList2;
  available;
  constructor(size) {
    this.capacity = size;
    this.available = size;
  }
  find(key) {
    const node = this.table.find(key);
    if (node) {
      this.history.push(node);
    }
    return node;
  }
  put(node, key) {
    if (this.available === 0) {
      const first = this.history.popFront();
      first?.unlink();
      first?.unlink2();
    } else {
      this.available--;
    }
    this.table.put(node, key);
    this.history.push(node);
  }
  clear() {
    while (true) {
      const node = this.history.popFront();
      if (!node) {
        this.available = this.capacity;
        return;
      }
      node.unlink();
      node.unlink2();
    }
  }
}

