class AnimBase {
  size = 0;
  type = null;
  labels = null;
  constructor(buf) {
    this.size = buf.g1();
    this.type = new Uint8Array(this.size);
    this.labels = new TypedArray1d(this.size, null);
    for (let i2 = 0;i2 < this.size; i2++) {
      this.type[i2] = buf.g1();
    }
    for (let i2 = 0;i2 < this.size; i2++) {
      const count = buf.g1();
      this.labels[i2] = new Uint8Array(count);
      for (let j = 0;j < count; j++) {
        this.labels[i2][j] = buf.g1();
      }
    }
  }
}

// vendor/client-ts/src/dash3d/AnimFrame.ts
init_Packet();

class AnimFrame {
  static list = [];
  delay = -1;
  base = null;
  size = 0;
  ti = null;
  tx = null;
  ty = null;
  tz = null;
  static opaque = [];
  static init(total) {
    this.list = new Array(total + 1);
    this.opaque = new Array(total + 1);
    for (let i2 = 0;i2 < total + 1; i2++) {
      this.opaque[i2] = true;
    }
  }
  static unpack(data) {
    const buf = new Packet(data);
    buf.pos = data.length - 8;
    const headLength = buf.g2();
    const tran1Length = buf.g2();
    const tran2Length = buf.g2();
    const delLength = buf.g2();
    let pos = 0;
    const head = new Packet(data);
    head.pos = pos;
    pos += headLength + 2;
    const tran1 = new Packet(data);
    tran1.pos = pos;
    pos += tran1Length;
    const tran2 = new Packet(data);
    tran2.pos = pos;
    pos += tran2Length;
    const del = new Packet(data);
    del.pos = pos;
    pos += delLength;
    const baseBuf = new Packet(data);
    baseBuf.pos = pos;
    const base = new AnimBase(baseBuf);
    const total = head.g2();
    const tempTi = new Int32Array(500);
    const tempTx = new Int32Array(500);
    const tempTy = new Int32Array(500);
    const tempTz = new Int32Array(500);
    for (let i2 = 0;i2 < total; i2++) {
      const id = head.g2();
      const frame = this.list[id] = new AnimFrame;
      frame.delay = del.g1();
      frame.base = base;
      const groupCount = head.g1();
      let lastGroup = -1;
      let current = 0;
      for (let j = 0;j < groupCount; j++) {
        if (!base.type) {
          throw new Error;
        }
        const flags = tran1.g1();
        if (flags > 0) {
          if (base.type[j] !== 0) {
            for (let group = j - 1;group > lastGroup; group--) {
              if (base.type[group] === 0) {
                tempTi[current] = group;
                tempTx[current] = 0;
                tempTy[current] = 0;
                tempTz[current] = 0;
                current++;
                break;
              }
            }
          }
          tempTi[current] = j;
          let defaultValue = 0;
          if (base.type[tempTi[current]] === 3 /* SCALE */) {
            defaultValue = 128;
          }
          if ((flags & 1) === 0) {
            tempTx[current] = defaultValue;
          } else {
            tempTx[current] = tran2.gsmarts();
          }
          if ((flags & 2) === 0) {
            tempTy[current] = defaultValue;
          } else {
            tempTy[current] = tran2.gsmarts();
          }
          if ((flags & 4) === 0) {
            tempTz[current] = defaultValue;
          } else {
            tempTz[current] = tran2.gsmarts();
          }
          lastGroup = j;
          current++;
          if (base.type[j] === 5 /* TRANSPARENCY */) {
            this.opaque[id] = false;
          }
        }
      }
      frame.size = current;
      frame.ti = new Int32Array(current);
      frame.tx = new Int32Array(current);
      frame.ty = new Int32Array(current);
      frame.tz = new Int32Array(current);
      for (let j = 0;j < current; j++) {
        frame.ti[j] = tempTi[j];
        frame.tx[j] = tempTx[j];
        frame.ty[j] = tempTy[j];
        frame.tz[j] = tempTz[j];
      }
    }
  }
  static get(id) {
    return AnimFrame.list[id];
  }
  static animateTransparencies(frame) {
    return frame === -1;
  }
}

