  async update() {
    if (this.errorStarted || this.errorLoading || this.errorHost) {
      return;
    }
    Client.loopCycle++;
    if (!this.ingame) {
      await this.updateTitle();
    } else {
      await this.updateGame();
    }
    await this.updateOnDemand();
  }
  async draw() {
    if (this.errorStarted || this.errorLoading || this.errorHost) {
      this.drawError();
      return;
    }
    Client.drawCycle++;
    if (!this.ingame) {
      await this.drawTitle();
    } else {
      this.drawGame();
    }
    if (this.isMobile) {
      MobileKeyboard_default.draw();
    }
    this.scrollCycle = 0;
  }
  refresh() {
    this.redrawFrame = true;
  }
  unload() {
    this.stream?.close();
    this.stream = null;
    if (this.mouseTrackingInterval) {
      clearInterval(this.mouseTrackingInterval);
      this.mouseTrackingInterval = null;
    }
    this.onDemand?.stop();
    this.onDemand = null;
    this.unloadTitle();
    this.drawArea = null;
  }
  async updateOnDemand() {
    if (!this.onDemand) {
      return;
    }
    await this.onDemand.run();
    while (true) {
      const req = this.onDemand.loop();
      if (req === null) {
        return;
      }
      if (req.archive === 0) {
        Model.unpack(req.file, req.data);
        if ((this.onDemand.getModelUse(req.file) & 98) != 0) {
          this.redrawSide = true;
          if (this.chatModalId !== -1) {
            this.redrawChat = true;
          }
        }
      }
      if (req.archive === 1 && req.data != null) {
        AnimFrame.unpack(req.data);
      }
      if (req.archive === 2 && this.midiSong === req.file && req.data != null) {
        this.saveMidi(req.data, this.midiFading);
      }
      if (req.archive === 3 && this.sceneState === 1) {
        if (this.mapBuildGroundData && this.mapBuildLocationData) {
          for (let i3 = 0;i3 < this.mapBuildGroundData.length; i3++) {
            if (this.mapBuildGroundFile[i3] == req.file) {
              this.mapBuildGroundData[i3] = req.data;
              if (req.data == null) {
                this.mapBuildGroundFile[i3] = -1;
                console.warn(`[377port] map land file=${req.file} completed with null data → skip`);
              }
              break;
            }
            if (this.mapBuildLocationFile[i3] == req.file) {
              this.mapBuildLocationData[i3] = req.data;
              if (req.data == null) {
                this.mapBuildLocationFile[i3] = -1;
                console.warn(`[377port] map loc file=${req.file} completed with null data → skip`);
              }
              break;
            }
          }
        }
      }
      if (req.archive === 93 && req.data != null && this.onDemand.hasMapLocFile(req.file)) {
        ClientBuild.prefetchLocations(new Packet(req.data), this.onDemand);
      }
    }
  }
  async updateTitle() {
    if (this.loginscreen === 0) {
      let x2 = (this.sWid / 2 | 0) - 80;
      let y = (this.sHei / 2 | 0) + 20;
      y += 20;
      if (this.mouseClickButton === 1 && this.mouseClickX >= x2 - 75 && this.mouseClickX <= x2 + 75 && this.mouseClickY >= y - 20 && this.mouseClickY <= y + 20) {
        this.loginscreen = 3;
        this.loginSelect = 0;
      }
      x2 = (this.sWid / 2 | 0) + 80;
      if (this.mouseClickButton === 1 && this.mouseClickX >= x2 - 75 && this.mouseClickX <= x2 + 75 && this.mouseClickY >= y - 20 && this.mouseClickY <= y + 20) {
        this.loginMes1 = "";
        this.loginMes2 = "Enter your username & password.";
        this.loginscreen = 2;
        this.loginSelect = 0;
      }
    } else if (this.loginscreen === 2) {
      let y = (this.sHei / 2 | 0) - 40;
      y += 30;
      y += 25;
      if (this.mouseClickButton === 1 && this.mouseClickY >= y - 15 && this.mouseClickY < y) {
        this.loginSelect = 0;
      }
      y += 15;
      if (this.mouseClickButton === 1 && this.mouseClickY >= y - 15 && this.mouseClickY < y) {
        this.loginSelect = 1;
      }
      let x2 = (this.sWid / 2 | 0) - 80;
      y = (this.sHei / 2 | 0) + 50;
      y += 20;
      if (this.mouseClickButton === 1 && this.mouseClickX >= x2 - 75 && this.mouseClickX <= x2 + 75 && this.mouseClickY >= y - 20 && this.mouseClickY <= y + 20) {
        this.loginRetryCount = 0;
        await this.login(this.loginUser, this.loginPass, false);
        if (this.ingame) {
          return;
        }
      }
      x2 = (this.sWid / 2 | 0) + 80;
      if (this.mouseClickButton === 1 && this.mouseClickX >= x2 - 75 && this.mouseClickX <= x2 + 75 && this.mouseClickY >= y - 20 && this.mouseClickY <= y + 20) {
        this.loginscreen = 0;
        this.loginUser = "";
        this.loginPass = "";
      }
      while (true) {
        const key = this.pollKey();
        if (key === -1) {
          return;
        }
        let valid = false;
        for (let i3 = 0;i3 < Client.CHARSET.length; i3++) {
          if (String.fromCharCode(key) === Client.CHARSET.charAt(i3)) {
            valid = true;
            break;
          }
        }
        if (this.loginSelect === 0) {
          if (key === 8 && this.loginUser.length > 0) {
            this.loginUser = this.loginUser.substring(0, this.loginUser.length - 1);
          }
          if (key === 9 || key === 10 || key === 13) {
            this.loginSelect = 1;
          }
          if (valid) {
            this.loginUser = this.loginUser + String.fromCharCode(key);
          }
          if (this.loginUser.length > 12) {
            this.loginUser = this.loginUser.substring(0, 12);
          }
        } else if (this.loginSelect === 1) {
          if (key === 8 && this.loginPass.length > 0) {
            this.loginPass = this.loginPass.substring(0, this.loginPass.length - 1);
          }
          if (key === 9 || key === 10 || key === 13) {
            this.loginSelect = 0;
          }
          if (valid) {
            this.loginPass = this.loginPass + String.fromCharCode(key);
          }
          if (this.loginPass.length > 20) {
            this.loginPass = this.loginPass.substring(0, 20);
          }
        }
      }
    } else if (this.loginscreen === 3) {
      const x2 = this.sWid / 2 | 0;
      let y = (this.sHei / 2 | 0) + 50;
      y += 20;
      if (this.mouseClickButton === 1 && this.mouseClickX >= x2 - 75 && this.mouseClickX <= x2 + 75 && this.mouseClickY >= y - 20 && this.mouseClickY <= y + 20) {
        this.loginscreen = 0;
      }
    }
  }
