// tools/harness/script/browser/quest/snapshot.ts
init_api();
var KNOWN_VARPS = {
  tbwt_main: 320,
  tbwt_tiadeche: 725,
  tbwt_tinsay: 726,
  tbwt_tamayu: 727,
  tbwt_lubufu: 728,
  tbwt_flags: 729,
  junglepotion: 175
};
function takeSnapshot(extraVarps = {}) {
  const inv = new Map;
  for (const it of Inventory.items()) {
    const n = it.name;
    if (!n)
      continue;
    inv.set(n, (inv.get(n) ?? 0) + it.count);
  }
  const varps = {};
  const ids = { ...KNOWN_VARPS, ...extraVarps };
  for (const [name, id] of Object.entries(ids)) {
    try {
      varps[name] = reader.varp(id) | 0;
    } catch {
      varps[name] = 0;
    }
  }
  const t = Game.tile();
  return {
    tile: t ? { x: t.x, z: t.z, level: t.level ?? 0 } : null,
    inv,
    varps,
    dialogOpen: ChatDialog.isOpen(),
    dialogOptions: ChatDialog.options()
  };
}

// tools/harness/script/browser/quest/QuestBot.ts
init_dialogPath();
var STALL_FAIL_AFTER = Number(globalThis.__questStallFail) || 12;
var STAGE_STALL_AFTER = Number(globalThis.__questStageStallFail) || 40;

class AdvanceDialog3 {
  bot;
  mod;
  constructor(bot, mod) {
    this.bot = bot;
    this.mod = mod;
  }
  validate() {
    if (this.mod.readStage() >= this.mod.completeStage)
      return false;
    return ChatDialog.isOpen();
  }
  lastMultiFp = "";
  async execute() {
    this.bot.noteDialogOpen();
    if (!ChatDialog.canContinue() && ChatDialog.options().length === 0 && !ChatDialog.modalMessage()) {
      await Execution.delayTicks(1);
      return;
    }
    if (ChatDialog.options().length > 0) {
      const fp = ChatDialog.fingerprint();
      if (fp === this.lastMultiFp) {
        await Execution.delayTicks(2);
        this.lastMultiFp = "";
        return;
      }
      const opts = ChatDialog.options();
      const pick = pickDialogOption(opts, this.bot.dialogPath);
      this.bot.log(`dialog: ${opts[pick]}`);
      this.lastMultiFp = fp;
      const ok = await ChatDialog.chooseOption(opts[pick]);
      if (!ok) {
        this.bot.log("dialog: chooseOption failed");
        this.lastMultiFp = "";
      }
      return;
    }
    if (ChatDialog.modalMessage()) {
      this.bot.log("dialog: continue (modal)");
      await ChatDialog.continue();
      return;
    }
    if (ChatDialog.canContinue()) {
      this.bot.log("dialog: continue");
      await ChatDialog.continue();
      return;
    }
    await Execution.delayTicks(1);
  }
}

class CloseMainModal {
  validate() {
    const m = reader.modals()?.main ?? -1;
    return m !== -1 && !ChatDialog.isOpen();
  }
  async execute() {
    actions.closeModal();
    await Execution.delayTicks(1);
  }
}

class AfterDialogStageRefresh {
  bot;
  mod;
  constructor(bot, mod) {
    this.bot = bot;
    this.mod = mod;
  }
  validate() {
    if (this.bot.sawDialogOpen && !ChatDialog.isOpen() && !this.bot.needsStageRefresh) {
      this.bot.needsStageRefresh = true;
      this.bot.log("dialog closed → will getvar stage before next action");
    }
    return this.bot.needsStageRefresh && !ChatDialog.isOpen() && Game.tile() !== null;
  }
  async execute() {
    await this.bot.refreshStageFromServer();
  }
}

class QuestDrive extends StageTask {
  mod;
  lastDesc = "";
  lastStallKey = "";
  stalls = 0;
  lastStage = -1;
  stageStalls = 0;
  constructor(bot, mod) {
    super(bot);
    this.mod = mod;
  }
  validate() {
    if (this.bot.needsStageRefresh)
      return false;
    return !ChatDialog.isOpen() && Game.sceneReady() && Game.tile() !== null && this.mod.readStage() < this.mod.completeStage;
  }
  async execute() {
    if (!Game.sceneReady()) {
      this.bot.log(`drive: wait sceneState=2 (now ${Game.sceneState()})`);
      await Game.waitSceneReady(60000, (m) => this.bot.log(m));
      return;
    }
    const ntEarly = Chat.noTriggerFor(20);
    if (ntEarly) {
      this.bot.hardFail(`FAIL-FAST: ${ntEarly}`);
      return;
    }
    const snap = takeSnapshot();
    const step = this.mod.decide(snap);
    if ((step.kind === "talk" || step.kind === "useOnNpc") && step.prefer?.length) {
      this.bot.dialogPath = step.prefer;
    }
    const desc = describe(step);
    const stage = this.mod.readStage();
    const stallKey = `${desc}|${stage}`;
    const tile = snap.tile;
    const tileHint = tile ? `@${tile.x},${tile.z}` : "";
    if (stage === this.lastStage && this.lastStage >= 0) {
      this.stageStalls++;
      if (this.stageStalls >= STAGE_STALL_AFTER) {
        if (stage >= this.mod.completeStage) {
          this.bot.markFinished();
          return;
        }
        this.bot.hardFail(`FAIL-FAST stage=${stage} stuck ×${this.stageStalls} last=${desc}${tileHint}`);
        return;
      }
    } else {
      this.stageStalls = 0;
      this.lastStage = stage;
    }
    if (stallKey === this.lastStallKey) {
      this.stalls++;
      if (this.stalls >= STALL_FAIL_AFTER) {
        const nt = Chat.noTriggerFor(24);
        const nih = Chat.nothingInteresting(12);
        const hint = nt ?? nih ?? `no stage progress ${tileHint}`;
        if (stage >= this.mod.completeStage) {
          this.bot.log(`stall after completeStage=${this.mod.completeStage} on ${desc} — treating as done (${hint})`);
          this.bot.markFinished();
          return;
        }
        this.bot.hardFail(`FAIL-FAST stall on ${desc} ×${this.stalls} stage=${stage}: ${hint}`);
        return;
      }
    } else {
      this.stalls = 0;
      this.lastStallKey = stallKey;
      this.lastDesc = desc;
      this.bot.log(`step ${desc} stage=${stage}${tileHint}`);
    }
    if (step.kind === "done")
      return;
    try {
      const ok = await executeStep(step, {
        log: (m) => this.bot.log(m),
        snap: () => takeSnapshot()
      });
      if (!ok) {
        const nt = Chat.noTriggerFor(20);
        if (nt) {
          this.bot.hardFail(`FAIL-FAST: ${nt}`);
          return;
        }
        this.bot.log(`step failed: ${desc}`);
        await Execution.delayTicks(2);
      }
    } catch (e) {
      if (e instanceof QuestHardFail || e?.name === "QuestHardFail") {
        this.bot.hardFail(String(e.message ?? e));
        return;
      }
      throw e;
    }
  }
}
function describe(step) {
  switch (step.kind) {
    case "custom":
      return `custom:${step.name}`;
    case "talk":
      return `talk:${step.npc}`;
    case "walk":
      return `walk:${step.tile.x},${step.tile.z}`;
    case "interactLoc":
      return `${step.op}:${step.loc}`;
    case "jump":
      return `jump:${step.label ?? step.loc}→${step.toTile.x},${step.toTile.z}`;
    case "useOnLoc":
      return `useOnLoc:${step.item}->${step.loc}`;
    case "useOnNpc":
      return `useOnNpc:${step.item}${step.itemId != null ? `#${step.itemId}` : ""}->${step.npc}`;
    case "useOnItem":
      return `useOnItem:${step.use}->${step.target}`;
    case "equip":
      return `equip:${step.item}`;
    case "wait":
      return `wait:${step.reason}`;
    case "done":
      return "done";
  }
}

class QuestBot extends TaskBot {
  mod;
  loopTicks = 1;
  idleTicks = 1;
  finished = false;
  failReason = null;
  dialogPath = [];
  needsStageRefresh = false;
  sawDialogOpen = false;
  constructor(mod) {
    super();
    this.mod = mod;
  }
  done() {
    return this.finished || this.mod.readStage() >= this.mod.completeStage;
  }
  noteDialogOpen() {
    this.sawDialogOpen = true;
  }
  async refreshStageFromServer() {
    const name = this.mod.stageVarName;
    if (!name) {
      this.needsStageRefresh = false;
      this.sawDialogOpen = false;
      await Execution.delayTicks(1);
      return;
    }
    const before = this.mod.readStage();
    this.log(`dialog closed → getvar ${name} (was ${before})`);
    actions.cheat(`getvar ${name}`);
    const want = `get ${name.toLowerCase()}:`;
    let value = null;
    for (let i3 = 0;i3 < 14; i3++) {
      await Execution.delayTicks(1);
      const hit = Chat.texts(28).find((t) => t.toLowerCase().includes(want));
      if (!hit)
        continue;
      const m = hit.match(/:\s*(?:to\s*)?(-?\d+)/i);
      if (m) {
        value = parseInt(m[1], 10);
        break;
      }
    }
    if (value != null && Number.isFinite(value)) {
      if (this.mod.applyServerStage) {
        this.mod.applyServerStage(value);
      } else {
        globalThis.__questServerStage = value;
      }
      this.log(`stage now ${name}=${value} (was ${before})`);
    } else {
      this.log(`stage refresh: no getvar reply for ${name}`);
    }
    this.needsStageRefresh = false;
    this.sawDialogOpen = false;
    await Execution.delayTicks(1);
  }
  hardFail(reason) {
    this.failReason = reason;
    this.log(reason);
    this.stop();
  }
  markFinished() {
    this.finished = true;
    this.stop();
  }
  async onStart() {
    this.log(`QuestBot ${this.mod.id} — ${this.mod.name}`);
    this.failReason = null;
    this.dialogPath = [];
    this.needsStageRefresh = false;
    this.sawDialogOpen = false;
    ScriptControl.clearStop();
    await Execution.delayUntil(() => Game.sceneReady() && Game.tile() !== null, 90000);
    if (!Game.sceneReady()) {
      this.log(`warn: starting with sceneState=${Game.sceneState()} (want 2)`);
    }
    if (this.mod.setup) {
      this.log("setup… (after scene ready)");
      await Game.waitSceneReady(60000, (m) => this.log(m));
      await this.mod.setup({
        log: (m) => this.log(m),
        snap: () => takeSnapshot()
      });
    }
    const seed = this.mod.decide(takeSnapshot());
    if (seed.kind === "talk" && seed.prefer?.length) {
      this.dialogPath = seed.prefer;
      this.log(`dialog path: ${seed.prefer.join(" → ")}`);
    }
    this.add(new AdvanceDialog3(this, this.mod), new AfterDialogStageRefresh(this, this.mod), new CloseMainModal, new QuestDrive(this, this.mod));
  }
  async run(maxMs = 45 * 60000) {
    const result = await super.run(maxMs);
    if (this.failReason) {
      this.log(`quest hard-fail: ${this.failReason}`);
      return `fail:${this.failReason.slice(0, 120)}`;
    }
    if (this.mod.readStage() >= this.mod.completeStage) {
      this.finished = true;
      this.log(`quest complete stage=${this.mod.readStage()}`);
      return "done";
    }
    return result;
  }
}

